CREATE PROCEDURE Supp_PROC_Stock_ProdPieces_Update (@Id Int,@SizeId Int,@ProdPcs Int)  AS  DECLARE @Coycode Int,@Ordid Int,@StyleNo Varchar(20),@StageId Int,@PartId Int,@GodId Int,@ColId Int,@StockQty Int,@SourceStageId Int,@FinalStage Char(1),@SeqNo int,@PartyId Int,@PcsStockId Int ,@OldId Int,@OldCoycode Int,@OldOrdid Int,@OldStyleNo Varchar(20),@OldStageId Int,@OldPartId Int,@OldGodId Int,@OldColId Int,@OldSizeId Int,@OldStockQty Int,@OldSourceStageId Int,@OldFinalStage Char(1),@OldSeqNo int,@OldPartyId Int ,@OldPcsStockId Int,@Rework Int,@RejectionTypeId Int ,@LotNo Varchar(15),@LotID int        Select @OldId=@Id      
Select @OldCoycode = CoyId From Trs_SuppProdentry Where Id=@OldId       
select @OldPartyId = 0       
SELECT @OldOrdid = OrdId From Trs_SuppProdentry Where Id=@OldId   
SELECT @OldStyleNo = StyleNo From Trs_SuppProdentry Where Id=@OldId    
SELECT @OldStageid = StageId From Trs_SuppProdentry Where Id=@OldId    
SELECT @OldPartId = PartId From Trs_SuppProdentry Where Id=@OldId    
SELECT @OldGodId = GodId From Trs_SuppProdentry Where Id=@OldId    
SELECT @Rework = Rework From Trs_SuppProdentry Where Id=@OldId    
SELECT @RejectionTypeId = RejectionTypeId From Trs_SuppProdentry Where Id=@OldId    
Select @OldSeqNo = SeqNo From Trs_SuppProdentry Inner Join Prod_Sequence On Trs_SuppProdentry.OrdId=Prod_Sequence.OrdId And Trs_SuppProdentry.StyleNo=Prod_Sequence.StyleNo And Trs_SuppProdentry.StageId=Prod_Sequence.StageId Where Id=@OldId    
SELECT @OldFinalStage = Mas_Dept.SemiFinish From Trs_SuppProdentry Inner Join Mas_JobWrkComp On Trs_SuppProdentry.StageId=Mas_JobWrkComp.Id Inner Join Mas_Dept On Mas_JobWrkComp.DeptId=Mas_Dept.DeptId Where Trs_SuppProdentry.Id=@OldId   
SELECT @OldColId = ClrId From Trs_SuppProdentry Where Id=@OldId   

SELECT @OldSizeId = @SizeId   SELECT @OldSourceStageId = SourceStageId From Trs_SuppProdentry Where Id=@OldId   SELECT @OldStockQty = ProdPcs From Trs_SuppProdentryQty Where Id=@OldId  and Sizid = @SizeId   SELECT @LotId = IsNull(LotId,0) From Trs_SuppProdentry Where Id=@OldId    if @OldStageId =-2 begin   SELECt @OldSourceStageId = -2  end  begin if @OldFinalStage='F'    begin    If EXISTS (select * from SuppPcs_StockTable Inner Join SuppPcs_StockTableQty On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId INNER JOIN Trs_Supp_ProdEntry_SourceStageDtl ON  SuppPcs_StockTable.PartId = Trs_Supp_ProdEntry_SourceStageDtl.PartId And SuppPcs_StockTable.StageId  = Trs_Supp_ProdEntry_SourceStageDtl.SourceStageId where coycode=@Oldcoycode and Ordid=@OldOrdid and StyleNo=@OldStyleNo and LotId = @LotId and GodId=@OldGodId and PartyId=@OldPartyId)    begin   Select @OldPcsStockId=PcsStockId From SuppPcs_StockTable where coycode=@Oldcoycode and  Ordid=@OldOrdid and StyleNo=@OldStyleNo and LotId = @LotId and Stageid=@OldStageid and GodId=@OldGodId and PartyId=@OldPartyId  /*Print 'as2' Print 'as' + str(@OldOrdid) Print 'as' + (@OldStyleno) Print 'as' + str(@oldSizeId)  Print 'as' + str(@Id) Print 'as' + str(@OldSourceStageId)  Print 'as' + str(@OldStageid) Print 'as' + str(@Lotid)  Print 'as' + str(@OldColid)  Print 'as' + str(@OldPartyid) */   If EXISTS (select * from SuppPcs_StockTable Inner Join SuppPcs_StockTableQty On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId INNER JOIN Trs_Supp_ProdEntry_SourceStageDtl ON  SuppPcs_StockTable.PartId = Trs_Supp_ProdEntry_SourceStageDtl.PartId And SuppPcs_StockTable.StageId  = Trs_Supp_ProdEntry_SourceStageDtl.SourceStageId where coycode=@Oldcoycode and Ordid=@OldOrdid and StyleNo=@OldStyleNo and LotID = @LotId and  GodId=@OldGodId and PartyId=@OldPartyId and SuppPcs_StockTableQty.SizeId=@OldSizeId  and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')=Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=Case When IsNull(@Rework,0) =0 Then 0 Else @RejectionTypeId End)   Begin   If @OldStageId<>1 And ( Select IsNull(PcsType,'Piece') From Mas_JobWrkComp Where Id=@OldStageId)='Piece'  Begin  Update SuppPcs_StockTableQty Set SuppPcs_StockTableQty.StockQty=SuppPcs_StockTableQty.StockQty+(@OldStockQty*IsNull(OrderQtyDtl.PcsPerColor,1)) From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId  INNER JOIN OrderQtyDtl on SuppPcs_StockTable.Ordid = OrderQtyDtl.Ordid And SuppPcs_StockTable.Styleno = OrderQtyDtl.StyleNo And OrderQtyDtl.ColId = SuppPcs_StockTableQty.Colid   And OrderQtyDtl.SizeId = SuppPcs_StockTableQty.SizeId And OrderQtyDtl.PartId = SuppPcs_StockTable.PartID  LEFT OUTER JOIN Mas_Lot ON OrderQtyDtl.LotNo = Mas_Lot.LotName	 INNER JOIN Trs_Supp_ProdEntry_SourceStageDtl ON  SuppPcs_StockTable.PartId = Trs_Supp_ProdEntry_SourceStageDtl.PartId And SuppPcs_StockTable.StageId  = Trs_Supp_ProdEntry_SourceStageDtl.SourceStageId where Trs_Supp_ProdEntry_SourceStageDtl.Id = @OldId and coycode=@Oldcoycode and SuppPcs_StockTable.Ordid=@OldOrdid and SuppPcs_StockTable.StyleNo=@OldStyleNo and LotID = @LotId and GodId=@OldGodId and PartyId=@OldPartyId   And SuppPcs_StockTableQty.SizeId=@OldSizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')=Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End    End   End   Else   Begin   If @OldStageId<>1  Begin   INSERT INTO SuppPcs_StockTableQty (PcsStockId,colid,Sizeid,StockQty,ProductionQty,GoodPcsFlag,RejectionTypeId) VALUES (@OldPcsStockId,@OldColId,@OldSizeid,@OldStockQty,@OldStockQty,Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End,Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End)   End   If @OldStageId<>1 And (Select IsNull(PcsType,'Piece') From Mas_JobWrkComp Where Id=@OldStageId)='Piece'   begin    Update SuppPcs_StockTableQty Set SuppPcs_StockTableQty.StockQty=SuppPcs_StockTableQty.StockQty-(@OldStockQty * isnull(orderqtydtl.pcspercolor,1)) ,SuppPcs_StockTableQty.ProductionQty=SuppPcs_StockTableQty.ProductionQty-@OldStockQty From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId  INNER JOIN OrderQtyDtl on SuppPcs_StockTable.Ordid = OrderQtyDtl.Ordid And SuppPcs_StockTable.Styleno = OrderQtyDtl.StyleNo And OrderQtyDtl.CmbClrID = SuppPcs_StockTableQty.Colid  And OrderQtyDtl.SizeId = SuppPcs_StockTableQty.SizeId  /*And OrderQtyDtl.PartId = SuppPcs_StockTable.PartID  */ LEFT OUTER JOIN Mas_Lot ON OrderQtyDtl.LotNo = Mas_Lot.LotName	 where coycode=@Oldcoycode and SuppPcs_StockTable.Ordid=@OldOrdid and SuppPcs_StockTable.StyleNo=@OldStyleNo and LotID = @LotId and Stageid=@OldStageId and SuppPcs_StockTable.PartId=@OldPartId and GodId=@OldGodId and PartyId=@OldPartyId and SuppPcs_StockTableQty.ColId=@OldColid and SuppPcs_StockTableQty.SizeId=@OldSizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')='G' and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=0  End   End   End   Else   begin   If @OldStageId<>1   Begin  Select @OldPcsStockId=Max(IsNull(PcsStockId,0))+1 From SuppPcs_StockTable   INSERT INTO SuppPcs_StockTable (Coycode,Ordid,styleNo,Stageid,PartId,SeqNo,GodId,PcsStockId,PartyId,LotId) VALUES (@OldCoycode,@OldOrdid,@OldStyleNo,@OldSourceStageid,@OldPartId,@OldSeqNo,@OldGodId,@OldPcsStockId,@OldPartyId,@LotId)   INSERT INTO SuppPcs_StockTableQty (PcsStockId,colid,Sizeid,StockQty,ProductionQty,GoodPcsFlag,RejectionTypeId) VALUES (@OldPcsStockId,@OldColId,@OldSizeid,@OldStockQty,@OldStockQty,Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End,Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End)   End   End   End   End   if  @OldFinalStage='S'  BEGIN   /*Print 'as7'  */ If EXISTS (select * from SuppPcs_StockTable Inner Join SuppPcs_StockTableQty On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId where coycode=@Oldcoycode and Ordid=@OldOrdid and StyleNo=@OldStyleNo and LotId = @LotID and Stageid=@OldSourceStageid and PartId=@OldPartId and GodId=@OldGodId and PartyId=@OldPartyId)     begin       Select @OldPcsStockId=PcsStockId From SuppPcs_StockTable where coycode=@Oldcoycode and Ordid=@OldOrdid and StyleNo=@OldStyleNo and LotId = @LotID and Stageid=@OldStageid and PartId=@OldPartId and GodId=@OldGodId and PartyId=@OldPartyId   If EXISTS (select * from SuppPcs_StockTable Inner Join SuppPcs_StockTableQty On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId where coycode=@Oldcoycode and Ordid=@OldOrdid and StyleNo=@OldStyleNo and LotId = @LotId and Stageid=@OldSourceStageid and PartId=@OldPartId and GodId=@OldGodId and PartyId=@OldPartyId and SuppPcs_StockTableQty.ColId=@OldColid and SuppPcs_StockTableQty.SizeId=@OldSizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')=Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End)  Begin    /*Print 'as9' */  If @OldStageId<>1 And (Select IsNull(PcsType,'Piece') From Mas_JobWrkComp Where Id=@OldStageId)='Piece'    Begin  Update SuppPcs_StockTableQty Set SuppPcs_StockTableQty.StockQty=SuppPcs_StockTableQty.StockQty+@OldStockQty,SuppPcs_StockTableQty.ProductionQty=SuppPcs_StockTableQty.ProductionQty+@OldStockQty From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId where coycode=@Oldcoycode and Ordid=@OldOrdid and StyleNo=@OldStyleNo and LotId = @LotId and Stageid=@OldSourceStageid and PartId=@OldPartId and GodId=@OldGodId and PartyId=@OldPartyId and SuppPcs_StockTableQty.ColId=@OldColid and SuppPcs_StockTableQty.SizeId=@OldSizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')=Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End    End   End   Else   Begin  If @OldStageId<>1  Begin      INSERT INTO SuppPcs_StockTableQty (PcsStockId,colid,Sizeid,StockQty,ProductionQty,GoodPcsFlag,RejectionTypeId) VALUES (@OldPcsStockId,@OldColId,@OldSizeid,@OldStockQty,@OldStockQty,Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End,Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End)   End   End   End   Else   begin   If @OldStageId<>1   Begin   Select @OldPcsStockId=Max(IsNull(PcsStockId,0))+1 From SuppPcs_StockTable   INSERT INTO  SuppPcs_StockTable (Coycode,Ordid,styleNo,Stageid,PartId,SeqNo,GodId,PcsStockId,PartyId,LotId) VALUES (@OldCoycode,@OldOrdid,@OldStyleNo,@OldSourceStageid,@OldPartId,@OldSeqNo,@OldGodId,@OldPcsStockId,@OldPartyId,@LotId)   INSERT INTO SuppPcs_StockTableQty (PcsStockId,colid,Sizeid,StockQty,ProductionQty,GoodPcsFlag,RejectionTypeId) VALUES (@OldPcsStockId,@OldColId,@OldSizeid,@OldStockQty,@OldStockQty,Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End,Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End)  End  End  End  Select @Id=@Id   Select @Coycode = CoyId From Trs_SuppProdentry Where Id=@Id   select @PartyId = 0  SELECT @Ordid = OrdId From Trs_SuppProdentry Where Id=@Id   SELECT @StyleNo = StyleNo From Trs_SuppProdentry Where Id=@Id   SELECT @Stageid = StageId From Trs_SuppProdentry Where Id=@Id  SELECT @PartId = PartId From Trs_SuppProdentry Where Id=@Id   SELECT @GodId = GodId From Trs_SuppProdentry Where Id=@Id   Select @SeqNo = SeqNo From Trs_SuppProdentry Inner Join Prod_Sequence On Trs_SuppProdentry.OrdId=Prod_Sequence.OrdId And Trs_SuppProdentry.StyleNo=Prod_Sequence.StyleNo And Trs_SuppProdentry.StageId=Prod_Sequence.StageId Where Id=@Id  SELECT @FinalStage = Mas_Dept.SemiFinish From Trs_SuppProdentry Inner Join Mas_JobWrkComp On Trs_SuppProdentry.StageId=Mas_JobWrkComp.Id Inner Join Mas_Dept On Mas_JobWrkComp.DeptId=Mas_Dept.DeptId Where Trs_SuppProdentry.Id=@Id  SELECT @ColId = ClrId From Trs_SuppProdentry Where Id=@Id   SELECT @SizeId = @SizeId   Select @SourceStageId = SourceStageId From Trs_SuppProdentry Where Id=@Id   SELECT @StockQty = @ProdPcs   begin   if @FinalStage='F'   begin    If EXISTS (select * from SuppPcs_StockTable where coycode=@coycode and Ordid=@Ordid and StyleNo=@StyleNo and LotId =@LotID and Stageid=@Stageid and PartId=@PartId and GodId=@GodId and PartyId=@PartyId)    begin    Select @PcsStockId=PcsStockId From SuppPcs_StockTable where coycode=@coycode and Ordid=@Ordid and StyleNo=@StyleNo and LotID = @LotID and Stageid=@Stageid and PartId=@PartId and GodId=@GodId and PartyId=@PartyId  If EXISTS (select * from SuppPcs_StockTable Inner Join SuppPcs_StockTableQty On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId where coycode=@coycode and Ordid=@Ordid and StyleNo=@StyleNo and LotID = @LotID and Stageid=@Stageid and PartId=@PartId and GodId=@GodId and PartyId=@PartyId and SuppPcs_StockTableQty.ColId=@Colid and  SuppPcs_StockTableQty.SizeId=@SizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')='G' and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=0)    Begin   If @StageId<>1 And (Select IsNull(PcsType,'Piece') From Mas_JobWrkComp Where Id=@StageId)='Piece'   Begin    Update SuppPcs_StockTableQty Set SuppPcs_StockTableQty.StockQty=SuppPcs_StockTableQty.StockQty+(@StockQty*IsNull(OrderQtyDtl.PcsPerColor,1)),SuppPcs_StockTableQty.ProductionQty=SuppPcs_StockTableQty.ProductionQty+@StockQty From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId  INNER JOIN OrderQtyDtl on SuppPcs_StockTable.Ordid = OrderQtyDtl.Ordid And SuppPcs_StockTable.Styleno = OrderQtyDtl.StyleNo And OrderQtyDtl.CmbClrID = SuppPcs_StockTableQty.Colid  And OrderQtyDtl.SizeId = SuppPcs_StockTableQty.SizeId /*And OrderQtyDtl.PartId = SuppPcs_StockTable.PartID */ LEFT OUTER JOIN Mas_Lot ON OrderQtyDtl.LotNo = Mas_Lot.LotName	   where  coycode=@coycode and SuppPcs_StockTable.Ordid=@Ordid and SuppPcs_StockTable.StyleNo=@StyleNo and LotId = @LotId and Stageid=@Stageid and SuppPcs_StockTable.PartId=@PartId and GodId=@GodId and PartyId=@PartyId and SuppPcs_StockTableQty.ColId=@Colid and SuppPcs_StockTableQty.SizeId=@SizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')='G' and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=0  End   End   Else   Begin   INSERT INTO SuppPcs_StockTableQty (PcsStockId,colid,Sizeid,StockQty,ProductionQty,GoodPcsFlag,RejectionTypeId) VALUES (@PcsStockId,@ColId,@Sizeid,@StockQty,@StockQty,'G',0)  End   End  Else begin   Select @PcsStockId=Max(IsNull(PcsStockId,0))+1 From SuppPcs_StockTable    INSERT INTO SuppPcs_StockTable (Coycode,Ordid,styleNo,Stageid,PartId,SeqNo,GodId,PcsStockId,PartyId,LotID) VALUES (@Coycode,@Ordid,@StyleNo,@Stageid,@PartId,@SeqNo,@GodId,@PcsStockId,@PartyId,@LotID)   INSERT INTO SuppPcs_StockTableQty (PcsStockId,colid,Sizeid,StockQty,ProductionQty,GoodPcsFlag,RejectionTypeId) VALUES (@PcsStockId,@ColId,@Sizeid,@StockQty,@StockQty,'G',0)  End   If @StageId<>1 And (Select IsNull(PcsType,'Piece') From Mas_JobWrkComp Where Id=@StageId)='Piece'   begin  /* colid removed by asl for packing qty reduce means update in pre stage - in above already added qty here diff qty minus */  Update SuppPcs_StockTableQty Set SuppPcs_StockTableQty.StockQty=SuppPcs_StockTableQty.StockQty-(@StockQty*IsNull(OrderQtyDtl.PcsPerColor,1)) From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable  On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId  INNER JOIN OrderQtyDtl on SuppPcs_StockTable.Ordid = OrderQtyDtl.Ordid And SuppPcs_StockTable.Styleno = OrderQtyDtl.StyleNo And OrderQtyDtl.ColId = SuppPcs_StockTableQty.Colid  And OrderQtyDtl.SizeId = SuppPcs_StockTableQty.SizeId And OrderQtyDtl.PartId = SuppPcs_StockTable.PartID  LEFT OUTER JOIN Mas_Lot ON OrderQtyDtl.LotNo = Mas_Lot.LotName	 INNER JOIN Trs_Supp_ProdEntry_SourceStageDtl ON  SuppPcs_StockTable.PartId = Trs_Supp_ProdEntry_SourceStageDtl.PartId And SuppPcs_StockTable.StageId  = Trs_Supp_ProdEntry_SourceStageDtl.SourceStageId where Trs_Supp_ProdEntry_SourceStageDtl.id = @id and coycode=@coycode and SuppPcs_StockTable.Ordid=@Ordid and SuppPcs_StockTable.StyleNo=@StyleNo and LotId = @LotId  and GodId=@GodId and PartyId=@PartyId And  SuppPcs_StockTableQty.SizeId=@SizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')=Case When IsNull(@Rework,0)=0 Then 'G' Else 'M' End and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End   Update SuppPcs_StockTableQty Set SuppPcs_StockTableQty.StockQty=SuppPcs_StockTableQty.StockQty-(@OldStockQty*IsNull(OrderQtyDtl.PcsPerColor,1)),SuppPcs_StockTableQty.ProductionQty=SuppPcs_StockTableQty.ProductionQty-@OldStockQty From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId  INNER JOIN OrderQtyDtl on SuppPcs_StockTable.Ordid = OrderQtyDtl.Ordid And SuppPcs_StockTable.Styleno = OrderQtyDtl.StyleNo And OrderQtyDtl.CmbClrID = SuppPcs_StockTableQty.Colid  And OrderQtyDtl.SizeId = SuppPcs_StockTableQty.SizeId /*And OrderQtyDtl.PartId = SuppPcs_StockTable.PartID  */  LEFT OUTER JOIN Mas_Lot ON OrderQtyDtl.LotNo = Mas_Lot.LotName	 where coycode=@Oldcoycode and SuppPcs_StockTable.Ordid=@OldOrdid and SuppPcs_StockTable.StyleNo=@OldStyleNo and LotId =@Lotid and Stageid=@OldStageId and SuppPcs_StockTable.PartId=@OldPartId and GodId=@OldGodId and PartyId=@OldPartyId and SuppPcs_StockTableQty.ColId=@OldColid and SuppPcs_StockTableQty.SizeId=@OldSizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')='G' and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=0  End  End  End  Begin if  @FinalStage='S'   BEGIN    If EXISTS (select * from SuppPcs_StockTable where coycode=@coycode and Ordid=@Ordid and StyleNo=@StyleNo and LotId =@LotId and Stageid=@Stageid and PartId=@PartId and GodId=@GodId and PartyId=@PartyId)    begin   Select @PcsStockId=PcsStockId From SuppPcs_StockTable where coycode=@coycode and Ordid=@Ordid and StyleNo=@StyleNo and LotId = @LotID and Stageid=@Stageid and PartId=@PartId and GodId=@GodId and PartyId=@PartyId  If EXISTS (select * from SuppPcs_StockTable Inner Join SuppPcs_StockTableQty On SuppPcs_StockTable.PcsStockId= SuppPcs_StockTableQty.PcsStockId where coycode=@coycode and Ordid=@Ordid and StyleNo=@StyleNo and LotId =@LotID and Stageid=@Stageid and PartId=@PartId and GodId=@GodId and PartyId=@PartyId and SuppPcs_StockTableQty.ColId=@Colid and SuppPcs_StockTableQty.SizeId=@SizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')='G' and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=0)  Begin  If @StageId<>1 And (Select IsNull(PcsType,'Piece') From Mas_JobWrkComp Where Id=@StageId)='Piece'  begin   Update SuppPcs_StockTableQty Set  SuppPcs_StockTableQty.StockQty=SuppPcs_StockTableQty.StockQty+@StockQty,SuppPcs_StockTableQty.ProductionQty=SuppPcs_StockTableQty.ProductionQty+@StockQty From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId where coycode=@coycode and Ordid=@Ordid and StyleNo=@StyleNo and LotId =@Lotid and Stageid=@Stageid and PartId=@PartId and GodId=@GodId and PartyId=@PartyId and SuppPcs_StockTableQty.ColId=@Colid and SuppPcs_StockTableQty.SizeId=@SizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')='G' and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=0 End /*Aslam  below qry*/  If @StageId=1 And (Select IsNull(PcsType,'Piece') From Mas_JobWrkComp Where Id=@StageId)='Piece'   begin  Update SuppPcs_StockTableQty Set SuppPcs_StockTableQty.StockQty=SuppPcs_StockTableQty.StockQty+@StockQty,SuppPcs_StockTableQty.ProductionQty =SuppPcs_StockTableQty.ProductionQty+@StockQty From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId where coycode=@coycode and Ordid=@Ordid and StyleNo=@StyleNo and LotId =@LotId and Stageid=@Stageid and PartId=@PartId and GodId=@GodId and PartyId=@PartyId and SuppPcs_StockTableQty.ColId=@Colid and SuppPcs_StockTableQty.SizeId=@SizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')='G' and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=0 End   If @StageId=-2 And (Select IsNull(PcsType,'Piece') From Mas_JobWrkComp Where Id=@StageId)='Bit'   begin    Update SuppPcs_StockTableQty Set SuppPcs_StockTableQty.StockQty=SuppPcs_StockTableQty.StockQty+@StockQty,SuppPcs_StockTableQty.ProductionQty =SuppPcs_StockTableQty.ProductionQty+@StockQty From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId where coycode=@coycode and Ordid=@Ordid and StyleNo=@StyleNo and LotId =@LotId and Stageid=@Stageid and PartId=@PartId and GodId=@GodId and PartyId=@PartyId and SuppPcs_StockTableQty.ColId=@Colid and SuppPcs_StockTableQty.SizeId=@SizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')='G' and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=0 End   End  Else   Begin    INSERT INTO SuppPcs_StockTableQty (PcsStockId,colid,Sizeid,StockQty,ProductionQty,GoodPcsFlag,RejectionTypeId) VALUES (@PcsStockId,@ColId,@Sizeid,@StockQty,@StockQty,'G',0)    End  End  Else   begin    Select @PcsStockId=Max(IsNull(PcsStockId,0))+1 From SuppPcs_StockTable    INSERT INTO SuppPcs_StockTable (Coycode,Ordid,styleNo,Stageid,PartId,SeqNo,GodId,PcsStockId,PartyId,LotId) VALUES (@Coycode,@Ordid,@StyleNo,@Stageid,@PartId,@SeqNo,@GodId,@PcsStockId,@PartyId,@LotId)    INSERT INTO SuppPcs_StockTableQty (PcsStockId,colid,Sizeid,StockQty,ProductionQty,GoodPcsFlag,RejectionTypeId) VALUES (@PcsStockId,@ColId,@Sizeid,@StockQty,@StockQty,'G',0)   End   If @StageId<>1 And (Select IsNull(PcsType,'Piece') From Mas_JobWrkComp Where Id=@StageId)='Piece'  begin  Update SuppPcs_StockTableQty Set SuppPcs_StockTableQty.StockQty=SuppPcs_StockTableQty.StockQty-@StockQty From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId where coycode=@coycode and Ordid=@Ordid and StyleNo=@StyleNo and LotId =@LotID and Stageid=@SourceStageId and PartId=@PartId and GodId=@GodId and PartyId=@PartyId and SuppPcs_StockTableQty.ColId=@Colid and SuppPcs_StockTableQty.SizeId=@SizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')=Case When IsNull(@Rework,0 )=0 Then 'G' Else 'M' End and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=Case When IsNull(@Rework,0)=0 Then 0 Else @RejectionTypeId End    Update SuppPcs_StockTableQty Set SuppPcs_StockTableQty.StockQty=SuppPcs_StockTableQty.StockQty-@OldStockQty, SuppPcs_StockTableQty.ProductionQty=SuppPcs_StockTableQty.ProductionQty-@OldStockQty From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId where coycode=@Oldcoycode and Ordid=@OldOrdid and StyleNo=@OldStyleNo and LotId =@Lotid and Stageid=@OldStageId and PartId=@OldPartId and GodId=@OldGodId and PartyId=@OldPartyId and SuppPcs_StockTableQty.ColId=@OldColid and SuppPcs_StockTableQty.SizeId=@OldSizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')='G' and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=0    End /*Aslam below query*/    If @StageId=1 And (Select IsNull(PcsType,'Piece') From Mas_JobWrkComp Where Id=@StageId)='Piece'    Begin     Update SuppPcs_StockTableQty Set SuppPcs_StockTableQty.StockQty=SuppPcs_StockTableQty.StockQty-@OldStockQty, SuppPcs_StockTableQty.ProductionQty=SuppPcs_StockTableQty.ProductionQty-@OldStockQty From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId where coycode=@Oldcoycode and Ordid=@OldOrdid and StyleNo=@OldStyleNo and LotId=@LotID and Stageid=@OldStageId and PartId=@OldPartId and GodId=@OldGodId and PartyId=@OldPartyId and SuppPcs_StockTableQty.ColId=@OldColid and SuppPcs_StockTableQty.SizeId=@OldSizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')='G' and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=0     End If @StageId=-2 And (Select IsNull(PcsType,'Piece') From Mas_JobWrkComp Where Id=@StageId)='Bit'    Begin       Update SuppPcs_StockTableQty Set SuppPcs_StockTableQty.StockQty=SuppPcs_StockTableQty.StockQty-@OldStockQty, SuppPcs_StockTableQty.ProductionQty=SuppPcs_StockTableQty.ProductionQty-@OldStockQty From SuppPcs_StockTableQty Inner Join SuppPcs_StockTable On SuppPcs_StockTable.PcsStockId=SuppPcs_StockTableQty.PcsStockId where coycode=@Oldcoycode and Ordid=@OldOrdid and StyleNo=@OldStyleNo and LotId=@LotID and Stageid=@OldStageId and PartId=@OldPartId and GodId=@OldGodId and PartyId=@OldPartyId and SuppPcs_StockTableQty.ColId=@OldColid and SuppPcs_StockTableQty.SizeId=@OldSizeId and IsNull(SuppPcs_StockTableQty.GoodPcsFlag,'G')='G' and IsNull(SuppPcs_StockTableQty.RejectionTypeId,0)=0     End  End     End 
 
